import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { lessonUrl } from '../../common/api';
import { duration, lessonIcons, t } from './util';
/** The course's sections and lessons, each lesson showing whether it is done, open or locked. */
export default class OutlineList extends Component {
  view() {
    const {
      course,
      items,
      current,
      compact
    } = this.attrs;
    let n = 0;
    return m("ol", {
      className: 'SyllabusOutline' + (compact ? ' SyllabusOutline--compact' : '')
    }, items.map(item => {
      if (item.kind === 'section') {
        return m("li", {
          key: 's' + item.id,
          className: "SyllabusOutline-section"
        }, item.title);
      }
      n++;
      const state = item.completed ? 'done' : item.locked ? 'locked' : 'open';
      const icon = item.completed ? 'fas fa-circle-check' : item.locked ? 'fas fa-lock' : lessonIcons[item.type];
      const label = m('[', null, m("span", {
        className: "SyllabusOutline-icon",
        "aria-hidden": "true"
      }, m(Icon, {
        name: icon
      })), m("span", {
        className: "SyllabusOutline-number"
      }, n, "."), m("span", {
        className: "SyllabusOutline-title"
      }, item.title), m("span", {
        className: "sr-only"
      }, t('outline.state_' + state)), item.status === 'draft' ? m("span", {
        className: "SyllabusBadge SyllabusBadge--draft"
      }, t('course.draft')) : null, item.preview && item.locked === null && !item.completed ? m("span", {
        className: "SyllabusBadge"
      }, t('outline.preview')) : null, !compact && item.durationMinutes ? m("span", {
        className: "SyllabusOutline-time"
      }, duration(item.durationMinutes)) : null);
      return m("li", {
        key: 'l' + item.id,
        className: 'SyllabusOutline-lesson SyllabusOutline-lesson--' + state + (current === item.id ? ' active' : ''),
        "aria-current": current === item.id ? 'page' : undefined
      }, m(Link, {
        href: lessonUrl(course, item)
      }, label));
    }));
  }
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/components/OutlineList', OutlineList);