import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { certificateUrl, completeLesson, courseUrl, enrol, lessonUrl, routeId, showLesson } from '../../common/api';
import OutlineList from '../components/OutlineList';
import ProgressBar from '../components/ProgressBar';
import Assignment from '../components/Assignment';
import { duration, failed, lessonIcons, t } from '../components/util';

/** Brainstorm's own quiz card, found at runtime: Syllabus never bundles any of Brainstorm. */
function brainstormScan() {
  const mod = globalThis.flarum?.reg?.get?.('ernestdefoe-brainstorm', 'forum/embed/scan');
  const fn = mod?.default ?? mod;
  return typeof fn === 'function' ? fn : null;
}

/** /courses/:id/lessons/:lesson — one lesson, or why it is locked. */
export default class LessonPage extends Page {
  lesson = null;
  missing = false;
  busy = false;
  certificate = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.load();
  }
  load() {
    return showLesson(routeId(m.route.param('lesson'))).then(({
      data
    }) => {
      // A lesson id under another course's address goes to its own.
      if (data.course.id !== routeId(m.route.param('id'))) {
        m.route.set(lessonUrl(data.course, data), {}, {
          replace: true
        });
        return;
      }
      this.lesson = data;
      app.setTitle(data.title);
      app.history.push('lesson', data.title);
      m.redraw();
    }, () => {
      this.missing = true;
      m.redraw();
    });
  }
  view() {
    const lesson = this.lesson;
    if (!lesson) {
      return m(PageStructure, {
        className: "SyllabusLessonPage",
        loading: !this.missing
      }, this.missing ? m("p", {
        className: "SyllabusEmpty"
      }, t('lesson.missing')) : null);
    }
    return m(PageStructure, {
      className: "SyllabusLessonPage",
      sidebar: () => this.sidebar(lesson)
    }, m("article", {
      className: "SyllabusLesson"
    }, m("header", {
      className: "SyllabusLesson-head"
    }, m("div", {
      className: "SyllabusLesson-type"
    }, m(Icon, {
      name: lessonIcons[lesson.type]
    }), " ", t('types.' + lesson.type), lesson.durationMinutes ? m("span", null, " \xB7 ", duration(lesson.durationMinutes)) : null, lesson.status === 'draft' ? m("span", {
      className: "SyllabusBadge SyllabusBadge--draft"
    }, t('course.draft')) : null), m("h2", {
      className: "SyllabusLesson-title"
    }, lesson.title), lesson.canEdit ? m(LinkButton, {
      className: "Button Button--icon Button--link SyllabusLesson-edit",
      icon: "fas fa-pen",
      "aria-label": t('lesson.edit'),
      href: app.route('syllabus.lesson.edit', {
        id: lesson.course.id + '-' + lesson.course.slug,
        lesson: lesson.id + '-' + lesson.slug
      })
    }) : null), lesson.locked ? this.lockedPanel(lesson) : this.content(lesson), m("nav", {
      className: "SyllabusLesson-nav",
      "aria-label": t('lesson.nav')
    }, lesson.prev ? m(LinkButton, {
      className: "Button",
      icon: "fas fa-arrow-left",
      href: lessonUrl(lesson.course, lesson.prev)
    }, lesson.prev.title) : m("span", null), lesson.next ? m(LinkButton, {
      className: "Button SyllabusLesson-next",
      href: lessonUrl(lesson.course, lesson.next)
    }, lesson.next.title, " ", m(Icon, {
      name: "fas fa-arrow-right"
    })) : null)));
  }
  sidebar(lesson) {
    return m("nav", {
      className: "SyllabusSide"
    }, m(Link, {
      className: "SyllabusSide-course",
      href: courseUrl(lesson.course)
    }, m(Icon, {
      name: "fas fa-arrow-left"
    }), " ", lesson.course.title), lesson.enrolled ? m(ProgressBar, {
      percent: lesson.progress.percent,
      done: lesson.progress.done,
      total: lesson.progress.total
    }) : null, m(OutlineList, {
      course: lesson.course,
      items: lesson.outline,
      current: lesson.id,
      compact: true
    }));
  }
  lockedPanel(lesson) {
    const reason = lesson.locked;
    return m("div", {
      className: "SyllabusLocked"
    }, m(Icon, {
      name: "fas fa-lock"
    }), m("p", null, t('lesson.locked_' + reason)), reason === 'enrol' && lesson.canEnrol ? m(Button, {
      className: "Button Button--primary",
      loading: this.busy,
      onclick: () => {
        this.busy = true;
        enrol(lesson.course.id).then(() => this.load(), failed).finally(() => {
          this.busy = false;
          m.redraw();
        });
      }
    }, t('course.enrol')) : null, reason === 'login' ? m(Button, {
      className: "Button Button--primary",
      onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
    }, t('course.login_to_enrol')) : null, reason === 'access' ? m(LinkButton, {
      className: "Button",
      href: courseUrl(lesson.course)
    }, t('lesson.see_course')) : null);
  }
  content(lesson) {
    return m('[', null, lesson.type === 'video' ? this.video(lesson) : null, lesson.bodyHtml ? m("div", {
      className: "SyllabusProse Post-body"
    }, m.trust(lesson.bodyHtml)) : null, lesson.type === 'quiz' ? this.quiz(lesson) : null, lesson.type === 'assignment' ? m(Assignment, {
      lesson: lesson,
      onchange: () => this.load()
    }) : null, lesson.canComplete ? m("div", {
      className: 'SyllabusComplete' + (lesson.completed ? ' is-done' : '')
    }, lesson.completed ? m('[', null, m("span", {
      className: "SyllabusComplete-done"
    }, m(Icon, {
      name: "fas fa-circle-check"
    }), " ", t('lesson.completed')), m(Button, {
      className: "Button Button--link",
      loading: this.busy,
      onclick: () => this.complete(lesson, false)
    }, t('lesson.undo'))) : m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-check",
      loading: this.busy,
      onclick: () => this.complete(lesson, true)
    }, t('lesson.mark_complete'))) : lesson.completed ? m("div", {
      className: "SyllabusComplete is-done"
    }, m("span", {
      className: "SyllabusComplete-done"
    }, m(Icon, {
      name: "fas fa-circle-check"
    }), " ", t('lesson.completed'))) : null, this.certificate ? m("div", {
      className: "SyllabusCongrats"
    }, m(Icon, {
      name: "fas fa-award"
    }), m("p", null, t('lesson.course_done')), m(LinkButton, {
      className: "Button Button--primary",
      href: certificateUrl(this.certificate)
    }, t('course.view_certificate'))) : null, lesson.discussion ? m("div", {
      className: "SyllabusDiscussion"
    }, m(Icon, {
      name: "far fa-comments"
    }), m("div", null, m("strong", null, t('lesson.ask')), m("p", null, t('lesson.ask_text', {
      count: Math.max(0, lesson.discussion.commentCount - 1)
    }))), m(LinkButton, {
      className: "Button",
      href: app.route('discussion', {
        id: lesson.discussion.id + '-' + lesson.discussion.slug
      })
    }, t('lesson.open_discussion'))) : null);
  }
  video(lesson) {
    const video = lesson.video;
    if (!video) return null;
    if (video.provider === 'file') {
      return m("div", {
        className: "SyllabusVideo"
      }, m("video", {
        controls: true,
        preload: "metadata",
        playsinline: true,
        src: video.fileUrl
      }));
    }
    return m("div", {
      className: "SyllabusVideo"
    }, m("iframe", {
      src: video.embedUrl,
      title: lesson.title,
      referrerpolicy: "strict-origin-when-cross-origin",
      allow: "accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen",
      allowfullscreen: true
    }));
  }
  quiz(lesson) {
    const quiz = lesson.quiz;
    if (!quiz) return m("p", {
      className: "SyllabusEmpty"
    }, t('lesson.quiz_missing'));
    return m("div", {
      className: "SyllabusQuiz"
    }, m("div", {
      className: "SyllabusQuiz-embed",
      oncreate: vnode => {
        const scan = brainstormScan();
        if (scan) scan(vnode.dom);
      }
    }, m("div", {
      className: "Post-body"
    }, m("p", null, m("a", {
      href: quiz.url
    }, quiz.title)))), !lesson.completed && lesson.enrolled ? m("div", {
      className: "SyllabusQuiz-check"
    }, m("p", null, t('lesson.quiz_hint')), m(Button, {
      className: "Button",
      icon: "fas fa-rotate",
      loading: this.busy,
      onclick: () => this.recheck()
    }, t('lesson.quiz_check'))) : null);
  }
  recheck() {
    this.busy = true;
    this.load().finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
  complete(lesson, done) {
    this.busy = true;
    completeLesson(lesson.id, done).then(({
      data
    }) => {
      lesson.completed = data.completed;
      lesson.progress = data.progress;
      lesson.outline.forEach(item => {
        if (item.kind === 'lesson' && item.id === lesson.id) item.completed = data.completed;
      });
      if (data.certificateCode) this.certificate = data.certificateCode;
      this.busy = false;
      // An "unlock in order" course opens the next lesson now: refresh the outline.
      if (done && lesson.course.sequential) this.load();
      m.redraw();
    }, e => {
      this.busy = false;
      failed(e);
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/pages/LessonPage', LessonPage);